import boto3
import json

def get_text(result, blocks_map):
    text = ''
    if 'Relationships' in result:
        for relationship in result['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    child = blocks_map[child_id]
                    if child['BlockType'] in ('WORD', 'LINE'):
                        text += child['Text'] + ' '
    return text.strip()

def find_tables(blocks):
    tables = []
    blocks_map = {block['Id']: block for block in blocks}
    for block in blocks:
        if block['BlockType'] == 'TABLE':
            cells = []
            if 'Relationships' in block:
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'CHILD':
                        for child_id in relationship['Ids']:
                            cell = blocks_map[child_id]
                            if cell['BlockType'] == 'CELL':
                                row_index = cell['RowIndex']
                                column_index = cell['ColumnIndex']
                                row_span = cell.get('RowSpan', 1)
                                column_span = cell.get('ColumnSpan', 1)
                                text = get_text(cell, blocks_map)
                                cells.append({
                                    'row': row_index,
                                    'column': column_index,
                                    'rowspan': row_span,
                                    'colspan': column_span,
                                    'text': text
                                })
            if cells:
                max_row = max(c['row'] for c in cells)
                table_rows = [[] for _ in range(max_row)]
                for cell in cells:
                    row = cell['row'] - 1
                    table_rows[row].append(cell)
                for row_cells in table_rows:
                    row_cells.sort(key=lambda c: c['column'])
                tables.append({'rows': table_rows})
    return tables

def extract_tables_from_document(document_path):
    """
    Extracts table cells and row structure from a document using AWS Textract.
    Supports images (PNG, JPEG, TIFF, PDF) and single-page PDFs.
    Returns a list of tables, each with 'rows' list of lists of cell dicts.
    """
    textract = boto3.client('textract', region_name='us-east-1')
    with open(document_path, 'rb') as file:
        document_bytes = file.read()
    response = textract.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES']
    )
    return find_tables(response['Blocks'])
